import { Meta } from '@storybook/addon-docs/blocks';
import tokensDocument from '@tokens/tokens.json';
import tokensCssRaw from '@tokens/dist/tokens.css?raw';
import tokensScssRaw from '@tokens/dist/tokens.scss?raw';
import tokensVarsJsRaw from '@tokens/dist/tokens.vars.js?raw';
import tokensVarsDtsRaw from '@tokens/dist/tokens.vars.d.ts?raw';
import { countTokens, downloadJson, downloadText } from './tokenStats';
import { TokenDisplay, getTokenDisplayItems, getTokensData } from '@az-digital/storybook-addon-tokens';
import { ColorSwatchGrid } from './ColorSwatchGrid';

{/* File links come from the tokens addon, which builds them for the branch this Storybook was built from. */}
export const { sourceFiles, artifacts } = getTokensData();

export const outputUrl = (file) => artifacts.find((artifact) => artifact.path.endsWith(`/${file}`))?.url;
export const githubUrl = sourceFiles[0]?.url;
export const tokensCssGithubUrl = outputUrl('tokens.css');
export const tokensScssGithubUrl = outputUrl('tokens.scss');
export const tokensVarsJsGithubUrl = outputUrl('tokens.vars.js');
export const tokensVarsDtsGithubUrl = outputUrl('tokens.vars.d.ts');
export const specUrl = 'https://www.designtokens.org/tr/2025.10/color/';
export const tokenCounts = countTokens(tokensDocument);

